fn touch_nmi_watchdog() {
// Pass on to the hardlockup detector selected via CONFIG_. Note that
// the hardlockup detector may not be arch-specific nor using NMIs
// and the arch_touch_nmi_watchdog() function will likely be renamed
// in the future.
arch_touch_nmi_watchdog();
touch_softlockup_watchdog();
}

fn trigger_single_cpu_backtrace(cpu: i32) -> bool {
unsafe { cpumask_backtrace(cpumask_of!(cpu), 1i32.wrapping_neg()) };
true
}

fn profile_hit(r#type: i32, ip: *mut ()) {
// Speedup for the common (no profiling enabled) case:
if unlikely__2!((unsafe { prof_on }) == r#type) != 0 {
unsafe { profile_hits(r#type, ip, 1u32) };
}
}

