//   CPU0            CPU1            CPU2
//
//   LOCK rq(0)->lock
//   sched-out X
//   sched-in Y
//   UNLOCK rq(0)->lock
//
//                                   LOCK rq(0)->lock // orders against CPU0
//                                   dequeue X
//                                   UNLOCK rq(0)->lock
//
//                                   LOCK rq(1)->lock
//                                   enqueue X
//                                   UNLOCK rq(1)->lock
//
//                   LOCK rq(1)->lock // orders against CPU2
//                   sched-out Z
//                   sched-in X
//                   UNLOCK rq(1)->lock
//
//
//  BLOCKING -- aka. SLEEP + WAKEUP
